**Tool Class — `WeatherTools.cs`**

```csharp
using ModelContextProtocol.Server;
using System.ComponentModel;
using System.Text.Json;

[McpServerToolType]
public class WeatherTools(HttpClient httpClient, ILogger<WeatherTools> logger)
{
    private const string BaseUrl = "https://api.weather.gov";

    [McpServerTool, Description("Get the current weather forecast for a US location by latitude/longitude.")]
    public async Task<string> GetForecast(
        [Description("Latitude of the location (e.g. 39.7456)")] double latitude,
        [Description("Longitude of the location (e.g. -97.0892)")] double longitude,
        CancellationToken cancellationToken = default)
    {
        logger.LogInformation("Fetching forecast for {Lat},{Lon}", latitude, longitude);

        // Step 1: resolve grid point
        httpClient.DefaultRequestHeaders.UserAgent.TryParseAdd("McpWeatherServer/1.0");
        var pointJson = await httpClient.GetStringAsync(
            $"{BaseUrl}/points/{latitude},{longitude}", cancellationToken);

        var point = JsonDocument.Parse(pointJson);
        var forecastUrl = point.RootElement
            .GetProperty("properties")
            .GetProperty("forecast")
            .GetString()!;

        // Step 2: get forecast
        var forecastJson = await httpClient.GetStringAsync(forecastUrl, cancellationToken);
        var forecast = JsonDocument.Parse(forecastJson);
        var periods = forecast.RootElement
            .GetProperty("properties")
            .GetProperty("periods");

        // Return first period's detail
        var current = periods[0];
        return $"{current.GetProperty("name")}: " +
               $"{current.GetProperty("detailedForecast")}";
    }

    [McpServerTool, Description("Get active weather alerts for a US state.")]
    public async Task<string> GetAlerts(
        [Description("Two-letter US state code (e.g. KS, CA)")] string state,
        CancellationToken cancellationToken = default)
    {
        var json = await httpClient.GetStringAsync(
            $"{BaseUrl}/alerts/active?area={state}", cancellationToken);

        var doc = JsonDocument.Parse(json);
        var features = doc.RootElement.GetProperty("features");

        if (features.GetArrayLength() == 0)
            return $"No active alerts for {state}.";

        var lines = new List<string>();
        foreach (var feature in features.EnumerateArray().Take(5))
        {
            var props = feature.GetProperty("properties");
            lines.Add($"- {props.GetProperty("headline")}");
        }
        return string.Join("\n", lines);
    }
}
```

**Program.cs — stdio transport**

```csharp
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Hosting;
using Microsoft.Extensions.Logging;

var builder = Host.CreateApplicationBuilder(args);

// CRITICAL: route all logs to stderr so stdout stays clean for JSON-RPC
builder.Logging.AddConsole(options =>
    options.LogToStandardErrorThreshold = LogLevel.Trace);

builder.Services.AddHttpClient();   // registers IHttpClientFactory + HttpClient

builder.Services.AddMcpServer()
    .WithStdioServerTransport()
    .WithToolsFromAssembly();        // discovers all [McpServerToolType] classes

await builder.Build().RunAsync();
```

---

### How DI works for MCP tools

The SDK supports **two injection styles**:

| Style | Class type | How services arrive |
|-------|-----------|---------------------|
| **Constructor injection** | Non-static class (shown above) | Services like `HttpClient`, `ILogger<T>` are injected via the primary constructor. The SDK creates the tool class from the DI container each invocation. |
| **Method parameter injection** | Static class | DI services appear directly as method parameters alongside user-facing parameters. The SDK distinguishes them automatically — DI services are **never** exposed in the tool schema. |

**Key rules:**
- `CancellationToken`, `IMcpServer`, `IProgress<T>`, and any DI-registered service are **auto-injected** and hidden from the LLM schema
- Only parameters with `[Description]` are visible to the LLM
- Register services in `Program.cs` (`AddHttpClient()`, `AddSingleton<T>()`, etc.) before calling `AddMcpServer()`
- `WithToolsFromAssembly()` discovers all tool classes via reflection; for AOT, use `.WithTools<WeatherTools>()` instead
